import{_ as c,C as l,o as a,c as p,a2 as o,b as n,w as t,a as r,E as i,a3 as d}from"./chunks/framework.CZqXuAiL.js";const C=JSON.parse('{"title":"Architecture Overview — OpenShield-L7","description":"OpenShield-L7 internals — crate layout, request data flow, the tokio threading model, the telemetry event bus, and on-disk file layout.","frontmatter":{"title":"Architecture Overview — OpenShield-L7","description":"OpenShield-L7 internals — crate layout, request data flow, the tokio threading model, the telemetry event bus, and on-disk file layout.","outline":"deep"},"headers":[],"relativePath":"openshield-l7/architecture/overview.md","filePath":"openshield-l7/architecture/overview.md","lastUpdated":1786524249000}'),h={name:"openshield-l7/architecture/overview.md"};function u(g,e,m,A,b,f){const s=l("Mermaid");return a(),p("div",null,[e[2]||(e[2]=o('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>OpenShield-L7 is a single Rust binary built as a workspace of seven crates. The data plane (listeners, routing, inspection, forwarding) is fully async on tokio; the control plane (admin API, metrics, config watching) shares the same runtime and talks to the data plane over a broadcast event bus.</p><hr><h2 id="crate-layout" tabindex="-1">Crate layout <a class="header-anchor" href="#crate-layout" aria-label="Permalink to &quot;Crate layout&quot;">​</a></h2><p>The workspace under <code>crates/</code> separates the contract, the data plane, and each concern into its own crate:</p><table tabindex="0"><thead><tr><th>Crate</th><th>Role</th></tr></thead><tbody><tr><td><code>osc-core</code></td><td>Contract: config models, events, state, pipeline traits, challenge, client-IP resolution</td></tr><tr><td><code>osc-proxy</code></td><td>Data plane: listeners, TLS/SNI, routing, upstream forwarding, transparent mode</td></tr><tr><td><code>osc-waf</code></td><td>Content/bot inspector (sqli / xss / traversal / rce / scanner / bot / custom rules)</td></tr><tr><td><code>osc-limit</code></td><td>Bans, ACLs, conn/rate limits, quotas, throttles, auto-mitigation</td></tr><tr><td><code>osc-metrics</code></td><td>Event-bus consumer: counters, ring buffers, aggregates, analytics</td></tr><tr><td><code>osc-api</code></td><td>Admin REST + SSE API</td></tr><tr><td><code>osc-cli</code></td><td>The <code>openshield-l7</code> binary: wiring, config dir, hot reload</td></tr></tbody></table><p>Shared dependency versions are pinned once in the workspace <code>Cargo.toml</code> (<code>dep.workspace = true</code> in members). Key libraries: <code>tokio</code> (multi-thread runtime), <code>hyper</code> 1.x (HTTP), <code>rustls</code> (TLS), <code>regex</code> (linear-time WAF matching), <code>notify</code> (file watcher), <code>arc-swap</code> (lock-free config snapshots), <code>serde_yaml</code>.</p><hr><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2>',9)),(a(),n(d,null,{default:t(()=>[i(s,{id:"mermaid-90",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20DATA%5B%22Data%20plane%20(osc-proxy%20%2B%20osc-waf%20%2B%20osc-limit)%22%5D%0A%20%20%20%20%20%20%20%20L%5B%22Listeners%3Cbr%2F%3Elisten_http%20%2F%20listen_https%22%5D%20--%3E%20R%5B%22HostIndex%3Cbr%2F%3Eexact%20%E2%86%92%20wildcard%20routing%22%5D%0A%20%20%20%20%20%20%20%20R%20--%3E%20IC%5B%22Inspector%20chain%3Cbr%2F%3Eban%2FACL%20%E2%86%92%20conn%20%E2%86%92%20rate%20%E2%86%92%20WAF%2Fbot%22%5D%0A%20%20%20%20%20%20%20%20IC%20--%3E%20UP%5B%22Upstream%20pool%3Cbr%2F%3Ekeep-alive%2C%20timeouts%2C%20backoff%22%5D%0A%20%20%20%20%20%20%20%20IC%20--%3E%20CH%5B%22Challenge%20manager%3Cbr%2F%3EPoW%20issue%2Fverify%2C%20HMAC%20cookies%22%5D%0A%20%20%20%20%20%20%20%20IC%20--%3E%20TH%5B%22Throttlers%20%2B%20quota%20meters%3Cbr%2F%3Ebps%20token%20buckets%2C%20monthly%20counters%22%5D%0A%20%20%20%20%20%20%20%20UP%20--%3E%20ORIGIN((%22Origin%20web%20servers%22))%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20CONTROL%5B%22Control%20plane%22%5D%0A%20%20%20%20%20%20%20%20CLI%5B%22osc-cli%3Cbr%2F%3Ebootstrap%20%C2%B7%20wiring%20%C2%B7%20watcher%22%5D%0A%20%20%20%20%20%20%20%20API%5B%22osc-api%3Cbr%2F%3EREST%20%2B%20SSE%20%3A9090%22%5D%0A%20%20%20%20%20%20%20%20MET%5B%22osc-metrics%3Cbr%2F%3Ecounters%20%C2%B7%20rings%20%C2%B7%20per-minute%20aggregates%22%5D%0A%20%20%20%20%20%20%20%20WATCH%5B%22notify%20watcher%3Cbr%2F%3E~300%20ms%20debounce%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20BUS%7B%7B%22Telemetry%20bus%3Cbr%2F%3Etokio%20broadcast%2C%20capacity%2065536%3Cbr%2F%3Edrop-on-congestion%22%7D%7D%0A%0A%20%20%20%20IC%20-.-%3E%7C%22one%20RequestEvent%20per%20request%22%7C%20BUS%0A%20%20%20%20CH%20-.-%3E%20BUS%0A%20%20%20%20TH%20-.-%3E%20BUS%0A%20%20%20%20BUS%20--%3E%20MET%0A%20%20%20%20BUS%20--%3E%20API%0A%20%20%20%20MET%20--%3E%20API%0A%20%20%20%20CLI%20--%3E%20WATCH%0A%20%20%20%20WATCH%20--%3E%7C%22validate%20%E2%86%92%20atomic%20swap%22%7C%20DATA%0A%20%20%20%20API%20--%3E%7C%22validate%20%E2%86%92%20persist%20%E2%86%92%20swap%22%7C%20DATA%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<table tabindex="0"><thead><tr><th>Component</th><th>Responsibility</th></tr></thead><tbody><tr><td><strong>Listeners</strong></td><td>Accept TCP on <code>listen_http</code> / <code>listen_https</code>; TLS terminated with per-site certs selected by SNI. Unknown SNI aborts the handshake.</td></tr><tr><td><strong>HostIndex</strong></td><td>Case-insensitive host map; exact match first, then longest-suffix wildcard; no match → <code>421</code>.</td></tr><tr><td><strong>Inspector chain</strong></td><td>Ordered, first non-<code>Allow</code> verdict wins: ban check + IP ACL → connection limits → rate limits → WAF/bot rules. Cheap stateless drops run first.</td></tr><tr><td><strong>Challenge manager</strong></td><td>Issues self-authenticating PoW seeds (<code>timestamp ‖ random ‖ HMAC</code>), verifies solves, mints/validates <code>osc_clear</code> clearance cookies. Stateless — the only secret is <code>data/challenge.secret</code>.</td></tr><tr><td><strong>Upstream pool</strong></td><td>Pooled keep-alive connections per site (<code>max_idle_per_host</code>, <code>keepalive_secs</code>), connect/read timeouts, 502-with-backoff on origin failure.</td></tr><tr><td><strong>Throttlers / quota meters</strong></td><td>Token buckets for <code>max_site_bps</code> / <code>max_ip_bps</code> shaping the response stream; monthly byte counters persisted under <code>data/quotas/</code> (atomic tmp+rename).</td></tr><tr><td><strong>Metrics engine</strong></td><td>Bus consumer: global + per-site counters, recent-event ring buffers, per-minute aggregate series, analytics tops/percentiles.</td></tr><tr><td><strong>Admin API</strong></td><td>REST + SSE on <code>admin.listen</code>; role-gated; writes go through the config store to disk, then hot-apply.</td></tr><tr><td><strong>Watcher</strong></td><td>Debounced <code>notify</code> on <code>config.yaml</code> + <code>sites.d/</code>; per-file reparse with last-good isolation.</td></tr></tbody></table><hr><h2 id="request-data-flow" tabindex="-1">Request data flow <a class="header-anchor" href="#request-data-flow" aria-label="Permalink to &quot;Request data flow&quot;">​</a></h2>',3)),(a(),n(d,null,{default:t(()=>[i(s,{id:"mermaid-181",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20C%20as%20Client%0A%20%20%20%20participant%20L%20as%20Listener%0A%20%20%20%20participant%20H%20as%20HostIndex%0A%20%20%20%20participant%20I%20as%20Inspector%20chain%0A%20%20%20%20participant%20B%20as%20Event%20bus%0A%20%20%20%20participant%20O%20as%20Origin%0A%0A%20%20%20%20C-%3E%3EL%3A%20TCP%20%2F%20TLS%20handshake%20(SNI)%0A%20%20%20%20L-%3E%3EL%3A%20resolve%20client%20IP%20(trusted-proxy%20aware)%0A%20%20%20%20L-%3E%3EH%3A%20Host%20header%20lookup%0A%20%20%20%20alt%20no%20site%20claims%20the%20host%0A%20%20%20%20%20%20%20%20H--%3E%3EC%3A%20421%20Misdirected%20Request%0A%20%20%20%20else%20site%20found%20(config%20snapshot)%0A%20%20%20%20%20%20%20%20H-%3E%3EI%3A%20request%20%2B%20site%20snapshot%0A%20%20%20%20%20%20%20%20I-%3E%3EI%3A%20ban%2FACL%20%E2%86%92%20conn%20%E2%86%92%20rate%20%E2%86%92%20WAF%2Fbot%0A%20%20%20%20%20%20%20%20alt%20verdict%20%3D%20block%0A%20%20%20%20%20%20%20%20%20%20%20%20I--%3E%3EC%3A%20403%20%2F%20429%20%2F%20503%20block%20page%0A%20%20%20%20%20%20%20%20else%20verdict%20%3D%20challenge%0A%20%20%20%20%20%20%20%20%20%20%20%20I--%3E%3EC%3A%20JS%20PoW%20page%20(or%20clearance%20check)%0A%20%20%20%20%20%20%20%20else%20verdict%20%3D%20allow%0A%20%20%20%20%20%20%20%20%20%20%20%20I-%3E%3EO%3A%20pooled%20upstream%20(XFF%20%2F%20PROXY%20%2F%20transparent%20source)%0A%20%20%20%20%20%20%20%20%20%20%20%20O--%3E%3EI%3A%20response%20stream%0A%20%20%20%20%20%20%20%20%20%20%20%20I--%3E%3EC%3A%20metered%20%2B%20throttled%20response%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20I-%3E%3EB%3A%20exactly%20one%20RequestEvent%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o(`<p>Every request — allowed, blocked, challenged, errored — produces <strong>exactly one</strong> telemetry event. That invariant is what makes the stats endpoints exact and the SSE stream complete.</p><hr><h2 id="threading-model" tabindex="-1">Threading model <a class="header-anchor" href="#threading-model" aria-label="Permalink to &quot;Threading model&quot;">​</a></h2><p>One <code>tokio</code> multi-thread runtime (<code>new_multi_thread</code>, threads named <code>openshield-l7</code>). Long-running tasks, spawned in this order at startup:</p><ol><li><strong><code>MetricsEngine</code></strong> — started first, so no bus events are missed.</li><li><strong><code>LimitEngine::run_maintenance</code></strong> — ban expiries, quota resets, mitigation windows; started before the proxy accepts traffic so connection gauges pair from the start.</li><li><strong><code>ProxyServer</code></strong> — all listeners and per-connection tasks.</li><li><strong><code>osc_api::serve</code></strong> — admin REST + SSE.</li><li><strong>The hot-reload watcher</strong> — debounced <code>notify</code> task.</li></ol><p>Shutdown is a <code>watch</code> channel broadcast: <code>SIGTERM</code>/<code>SIGINT</code> flips it, the proxy and API stop accepting and drain (bounded at 10 s), maintenance and watcher are aborted, exit code <code>0</code>. If the proxy or API task dies on its own (bind failure), the process exits <code>1</code>.</p><p>Concurrency properties worth knowing:</p><ul><li><strong>Config snapshots are <code>ArcSwap</code>-published.</strong> A request pins the site config snapshot it started on; a hot reload swaps the pointer — in-flight requests finish on the old config, new requests see the new one. No locks on the request path.</li><li><strong>The event bus is a tokio broadcast channel</strong> (default capacity 65536). Slow consumers drop events rather than applying backpressure to the data plane — telemetry never blocks proxying.</li><li><strong>Per-IP/per-site limiter state</strong> lives in <code>osc-limit</code> with counters preserved across reloads for unchanged rules; connection gauges are paired per request (<code>conn_bumped_*</code> flags) so releases exactly match takes.</li></ul><hr><h2 id="on-disk-layout" tabindex="-1">On-disk layout <a class="header-anchor" href="#on-disk-layout" aria-label="Permalink to &quot;On-disk layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;root&gt;/                                 (--root, default &quot;.&quot;)</span></span>
<span class="line"><span>├── config.yaml                         global config — watched</span></span>
<span class="line"><span>├── sites.d/</span></span>
<span class="line"><span>│   ├── &lt;site&gt;.yaml                     one file per site — watched, per-file isolation</span></span>
<span class="line"><span>│   └── example.yaml.disabled           template written when empty at bootstrap</span></span>
<span class="line"><span>├── certs/&lt;site&gt;/{fullchain,privkey}.pem</span></span>
<span class="line"><span>└── data/</span></span>
<span class="line"><span>    ├── challenge.secret                HMAC secret for PoW seeds + clearance cookies (0600)</span></span>
<span class="line"><span>    ├── quotas/                         monthly quota counters (atomic tmp+rename)</span></span>
<span class="line"><span>    └── snapshots/                      runtime state snapshots</span></span></code></pre></div><p>The production install maps this onto <code>/etc/openshield-l7</code> with the binary at <code>/usr/local/bin/openshield-l7</code> — see <a href="./../getting-started/installation">Installation</a>.</p><hr><h2 id="design-invariants" tabindex="-1">Design invariants <a class="header-anchor" href="#design-invariants" aria-label="Permalink to &quot;Design invariants&quot;">​</a></h2><ul><li><strong>The proxy never hosts content.</strong> The only originated bytes are block pages, challenge pages, and the admin API.</li><li><strong>Fail isolated, not open or closed.</strong> A broken site file affects only that file; origin failure means 502-with-backoff for that site, never a panic.</li><li><strong>Telemetry is lossy by design</strong> under congestion; the data plane is never slowed by observability.</li><li><strong>Files are the source of truth.</strong> The API is a validated writer to the same files, not a parallel config store.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><strong><a href="./transparent-ip">Transparent Client IP →</a></strong> — <code>IP_TRANSPARENT</code> mechanics and routing setups.</li><li><strong><a href="./testing">Testing &amp; Benchmarks →</a></strong> — the e2e battery and attack simulation.</li><li><strong><a href="./../user-guide/hot-reload">Hot Reload →</a></strong> — the reload pipeline from the operator side.</li></ul>`,17))])}const y=c(h,[["render",u]]);export{C as __pageData,y as default};
